312	func (s *APIV1Service) DeleteAttachment(ctx context.Context, request *v1pb.DeleteAttachmentRequest) (*emptypb.Empty, error) {
313		attachmentUID, err := ExtractAttachmentUIDFromName(request.Name)
314		if err != nil {
315			return nil, status.Errorf(codes.InvalidArgument, "invalid attachment id: %v", err)
316		}
317		user, err := s.fetchCurrentUser(ctx)
318		if err != nil {
319			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
320		}
321		if user == nil {
322			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
323		}
324		attachment, err := s.Store.GetAttachment(ctx, &store.FindAttachment{
325			UID:       &attachmentUID,
326			CreatorID: &user.ID,
327		})
328		if err != nil {
